<!doctype html><html lang='de'><head><meta charset='utf-8'><title>Matches</title><link rel='stylesheet' href='assets/css/style.css'></head><body><header><h1>Spiele</h1></header><main><table id='matches'><thead><tr><th>ID</th><th>Heim</th><th>Ergebnis</th><th>Auswärts</th><th>Status</th></tr></thead><tbody></tbody></table></main><script>async function load(){const r=await fetch('http://'+location.hostname+':8082/api/matches');const d=await r.json();const b=document.querySelector('#matches tbody');d.forEach(m=>{const tr=document.createElement('tr');tr.innerHTML=`<td>${m.id}</td><td>${m.home_team}</td><td>${m.home_goals ?? '-'}:${m.away_goals ?? '-'}</td><td>${m.away_team}</td><td>${m.status}</td>`;b.appendChild(tr);});}load();</script></body></html>